    ('provincial-french-beach-park', 'French Beach Park', 'provincial', 48.392727, -123.942632, 'South Island', 'A broad lawn meets a sand-and-pebble beach on the Strait of Juan de Fuca, with views toward the Olympic Mountains. Forest trails and a campground add to the appeal, while spring whale migrations make the shoreline a popular place to watch the water.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '687', NULL),
    ('provincial-gabriola-sands-park', 'Gabriola Sands Park', 'provincial', 49.19393, -123.860367, 'Gulf Islands', 'Two sandy beaches join across a narrow isthmus between Taylor Bay and Pilot Bay on Gabriola Island. This popular day-use park has open lawns for picnics and swimming, and its beaches and shallows support shorebirds and marine life.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '688', NULL),
