    ('provincial-strathcona-park', 'Strathcona Park', 'provincial', 49.592258, -125.690236, 'Central Island', 'Established in 1911, Strathcona is British Columbia''s oldest park and a vast mountain wilderness near the centre of Vancouver Island. Snowy peaks, alpine plateaus, lakes, waterfalls and forest draw hikers and campers through the warmer months and backcountry skiers in winter.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1125', NULL),
    ('provincial-strathcona-westmin-park', 'Strathcona - Westmin Park', 'provincial', 49.574561, -125.592441, 'Central Island', 'This unusual park encloses the active Myra Falls mine within the wider Strathcona wilderness. Away from the industrial site, its rugged forest setting offers hiking and backcountry camping opportunities.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1127', NULL),
