    ('provincial-west-lake-park', 'West Lake Park', 'provincial', 53.736417, -122.860784, 'Cariboo & Central Interior', 'A BC provincial park in the Cariboo & Central Interior collection. The map pin represents the largest official park polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1215', NULL),
    ('provincial-west-shawnigan-lake-park', 'West Shawnigan Lake Park', 'provincial', 48.641467, -123.650828, 'South Island', 'A small day-use park on Shawnigan Lake protects Douglas-fir forest and provides beach access for swimming and paddling. Picnic tables, toilets and short walking paths support relaxed summer visits.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1216', NULL),
    ('provincial-west-twin-park', 'West Twin Park', 'provincial', 53.349362, -120.537877, 'Cariboo & Central Interior', 'A BC provincial park in the Cariboo & Central Interior collection. The map pin represents the largest official park polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '4858', NULL),
    ('provincial-weymer-creek-park', 'Weymer Creek Park', 'provincial', 49.882751, -126.61557, 'North Island', 'Weymer Creek protects an extensive karst landscape and cave system near Tahsis, including habitat for the red-listed Keen''s long-eared myotis bat. Caves are ecologically sensitive, and BC Parks cautions against caving until a management plan is complete.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1218', NULL),
    ('provincial-whaleboat-island-marine-park', 'Whaleboat Island Marine Park', 'provincial', 49.07299, -123.692884, 'Southern Vancouver Island', 'A BC provincial park in the Southern Vancouver Island collection. The map pin represents the largest official park polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1219', NULL),
    ('provincial-whiskers-point-park', 'Whiskers Point Park', 'provincial', 54.905361, -122.936075, 'Cariboo & Central Interior', 'A BC provincial park in the Cariboo & Central Interior collection. The map pin represents the largest official park polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1221', NULL),
    ('provincial-white-lake-park', 'White Lake Park', 'provincial', 50.87881, -119.256554, 'Thompson & Okanagan', 'A BC provincial park in the Thompson & Okanagan collection. The map pin represents the largest official park polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1222', NULL),
    ('provincial-white-pelican-park', 'White Pelican Park', 'provincial', 52.283784, -123.029887, 'Cariboo & Central Interior', 'A BC provincial park in the Cariboo & Central Interior collection. The map pin represents the largest official park polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1223', NULL),
    ('provincial-white-ridge-park', 'White Ridge Park', 'provincial', 49.777527, -125.973322, 'North Island', 'White Ridge rises behind Gold River and protects internationally notable white limestone karst, caves and wildlife habitat. Its underground features are sensitive, so BC Parks advises against caving until a management plan is complete.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1224', NULL),
    ('provincial-white-river-park', 'White River Park', 'provincial', 50.140436, -126.033107, 'North Island', 'This small wilderness park protects old-growth forest and habitat for Roosevelt elk and black bears beside the White River. A short loop trail descends through large Douglas fir and red cedar to the water.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1225', NULL),
    ('provincial-whiteswan-lake-park', 'Whiteswan Lake Park', 'provincial', 50.137029, -115.494521, 'Kootenays', 'A BC provincial park in the Kootenays collection. The map pin represents the largest official park polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1226', NULL),
    ('provincial-windermere-lake-park', 'Windermere Lake Park', 'provincial', 50.421283, -115.967114, 'Kootenays', 'A BC provincial park in the Kootenays collection. The map pin represents the largest official park polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '4859', NULL),
    ('provincial-wire-cache-park', 'Wire Cache Park', 'provincial', 51.722571, -119.348352, 'Thompson & Okanagan', 'A BC provincial park in the Thompson & Okanagan collection. The map pin represents the largest official park polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1229', NULL),
    ('provincial-wistaria-park', 'Wistaria Park', 'provincial', 53.857094, -126.318873, 'Nechako', 'A BC provincial park in the Nechako collection. The map pin represents the largest official park polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1230', NULL),
    ('provincial-wood-mountain-ski-park', 'Wood Mountain Ski Park', 'provincial', 49.658012, -125.164887, 'Central Island', 'North of Comox Lake and west of Courtenay, Wood Mountain Ski Park is a roughly 240-acre park established in 1966. The provincial geographical names record says it was named for Clinton S. Wood and designated for recreation and wildlife preservation.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1232', NULL),
    ('provincial-woss-lake-park', 'Woss Lake Park', 'provincial', 50.060856, -126.626665, 'North Island', 'South of Woss on northern Vancouver Island, this undeveloped park protects part of Woss Lake and the steep forested slopes and snowfields of Rugged Mountain. Its remote lake and mountain setting offers a wilderness experience.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1234', NULL),
    ('provincial-wrinkly-face-park', 'Wrinkly Face Park', 'provincial', 50.039789, -119.309672, 'Thompson & Okanagan', 'A BC provincial park in the Thompson & Okanagan collection. The map pin represents the largest official park polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '5107', NULL),
    ('provincial-yahk-park', 'Yahk Park', 'provincial', 49.080462, -116.095896, 'Kootenays', 'A BC provincial park in the Kootenays collection. The map pin represents the largest official park polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1235', NULL),
    ('provincial-yalakom-park', 'Yalakom Park', 'provincial', 51.089552, -122.413257, 'South Coast', 'A BC provincial park in the South Coast collection. The map pin represents the largest official park polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '5377', NULL),
    ('provincial-yard-creek-park', 'Yard Creek Park', 'provincial', 50.902534, -118.823908, 'Thompson & Okanagan', 'A BC provincial park in the Thompson & Okanagan collection. The map pin represents the largest official park polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1237', NULL),
    ('regional-albert-head-lagoon-regional-park', 'Albert Head Lagoon Regional Park', 'regional', 48.39516, -123.490868, 'Capital Region', 'A sheltered lagoon and dune landscape ends at a cobble beach with views toward the Olympic Mountains. It is a compact stop for shoreline walks, birdwatching and a picnic.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-ayum-creek-regional-park', 'Ayum Creek Regional Park', 'regional', 48.391627, -123.66096, 'Capital Region', 'Forest and wetland surround the estuary where Ayum Creek reaches Sooke Basin. The creek is important habitat for salmon and trout; the park has no public facilities.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-beachcomber-regional-park', 'Beachcomber Regional Park', 'regional', 49.313002, -124.213611, 'Central Island', 'At the end of Nanoose’s Beachcomber Peninsula, this small oceanfront park pairs short woodland trails with rocky shoreline and tidal pools. Views reach across Craig Bay toward Parksville and Mount Arrowsmith, and across the Strait of Georgia to the mainland mountains.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-bear-hill-regional-park', 'Bear Hill Regional Park', 'regional', 48.545162, -123.40296, 'Capital Region', 'Woodland trails climb a hilly landscape of Douglas-fir, Garry oak and arbutus to a summit with views across the Saanich Peninsula toward Mount Baker and nearby islands. Spring brings wildflowers, and some routes are used by horseback riders.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-benson-creek-falls-regional-park', 'Benson Creek Falls Regional Park', 'regional', 49.192284, -124.079726, 'Central Island', 'This rugged, forested park follows creeks through steep ravines to waterfalls, including Ammonite Falls. The falls are reached by a rough hike of about 1.5 kilometres from Weigles Road or 2.5 kilometres from Creekside Place.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-bere-point-regional-park', 'Bere Point Regional Park', 'regional', 50.670833, -127.056667, 'Northern Islands', 'Six kilometres from Sointula, this wooded coastal campground sits close to the beach with views across Queen Charlotte Strait to the coastal mountains. A whale-watching platform overlooks the shore, and the Beautiful Bay Trail begins in the park.', 'https://www.rdmw.bc.ca/recreation-leisure/camping-information/bere-point/', 'Regional District of Mount Waddington + BC Geographical Names Office', 'bcgnis-22727', NULL),
    ('regional-brooks-point-regional-park', 'Brooks Point Regional Park', 'regional', 48.735746, -123.187155, 'Gulf Islands', 'On South Pender Island, trails cross coastal forest, meadow and a wetland boardwalk to rocky bluffs and beaches. Look across Boundary Pass toward the San Juan Islands and Mount Baker, and watch for spring chocolate lilies in the meadow.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-coats-marsh-regional-park', 'Coats Marsh Regional Park', 'regional', 49.154187, -123.814594, 'Gulf Islands', 'Wetlands and second-growth forest form Gabriola Island’s first protected wetland area. Rough trails offer a close look at the marsh and its birdlife.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-coles-bay-regional-park', 'Coles Bay Regional Park', 'regional', 48.631507, -123.465039, 'Capital Region', 'Short woodland trails lead to a pebble beach on Saanich Inlet. The sheltered shoreline is a popular summer swimming spot, with picnic tables and accessible toilets near the parking area.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-descanso-bay-regional-park', 'Descanso Bay Regional Park', 'regional', 49.182833, -123.858906, 'Gulf Islands', 'This oceanfront Gabriola park is a short distance from the ferry and village centre. Its wooded campground, small boat launch, shoreline coves and picnic area make it a base for kayaking, swimming and exploring the island.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-devonian-regional-park', 'Devonian Regional Park', 'regional', 48.364253, -123.537749, 'Capital Region', 'This small coastal conservation area has a wooded trail beside Sherwood Creek leading to a cobble beach. The shore opens to views of Juan de Fuca Strait, Race Rocks and the Olympic Mountains; Sherwood Pond is a birdwatching stop.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-east-point-regional-park', 'East Point Regional Park', 'regional', 48.782449, -123.047104, 'Gulf Islands', 'At Saturna Island’s eastern tip, coastal bluffs look toward the San Juan Islands and Washington mainland. The park connects with Gulf Islands National Park Reserve and is known for its open shoreline scenery.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-east-sooke-regional-park', 'East Sooke Regional Park', 'regional', 48.339419, -123.669949, 'Capital Region', 'A network of roughly 50 kilometres of trails crosses forest, marsh, open fields and rugged coast. The 10-kilometre Coast Trail links pocket beaches and rocky bays, with views across Juan de Fuca Strait to the Olympic Mountains.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-elk-beaver-lake-regional-park', 'Elk/Beaver Lake Regional Park', 'regional', 48.52232, -123.395954, 'Capital Region', 'Elk and Beaver Lakes have four beaches, picnic areas and about 15 kilometres of walking routes, including a 10-kilometre loop. Designated trails allow cycling and horseback riding, and Elk Lake has an accessible fishing dock and stocked rainbow trout.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-englishman-river-regional-park', 'Englishman River Regional Park', 'regional', 49.287303, -124.286889, 'Central Island', 'A broad river corridor protects salmon habitat, including a constructed side channel and community hatchery. The park’s open trails welcome walkers, cyclists and horseback riders, with wildlife such as elk and bears in the surrounding landscape.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-francis-king-regional-park', 'Francis/King Regional Park', 'regional', 48.484037, -123.448166, 'Capital Region', 'This forested conservation area pairs the universally accessible Elsie King Trail with a grove of old Douglas-fir trees. Additional trails connect to Thetis Lake Regional Park for a longer walk.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-george-hill-regional-park', 'George Hill Regional Park', 'regional', 48.815866, -123.312337, 'Capital Region', 'A steep forest trail on North Pender climbs to a broad viewpoint over Galiano, Mayne and Salt Spring islands. On clear days the Olympic Mountains are visible; the official trail starts from Ogden Road or Upper Terrace Road.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-gonzales-hill-regional-park', 'Gonzales Hill Regional Park', 'regional', 48.413732, -123.324787, 'Capital Region', 'Rocky knolls and Garry oak meadows lead to the 66-metre summit, where views span Victoria and the Sooke Hills. The historic Gonzales Observatory and spring wildflowers add interest to a short hilltop visit.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-greenspaces-alberni-clayoquot-bishop-park-8903', 'Bishop Park', 'regional', 49.27055, -124.966529, 'Southern Vancouver Island', 'An officially mapped regional park in the Southern Vancouver Island collection. The pin represents its largest published polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/6a2fea1b-0cc4-4fc2-8017-eaf755d516da', 'Alberni-Clayoquot Regional District via BC Local and Regional Greenspaces', '8903', NULL),
