    ('regional-metro-vancouver-sou', 'South Langley Regional Park', 'regional', 49.011106, -122.597703, 'South Coast', 'An officially mapped regional park in the South Coast collection. The pin represents its largest published polygon, not an entrance or trailhead.', 'https://open-data-portal-metrovancouver.hub.arcgis.com/datasets/metrovancouver::regional-parks-boundaries-open-data', 'Metro Vancouver Regional Parks', 'SOU', NULL),
    ('regional-metro-vancouver-sur', 'Surrey Bend Regional Park', 'regional', 49.203657, -122.743078, 'South Coast', 'An officially mapped regional park in the South Coast collection. The pin represents its largest published polygon, not an entrance or trailhead.', 'https://open-data-portal-metrovancouver.hub.arcgis.com/datasets/metrovancouver::regional-parks-boundaries-open-data', 'Metro Vancouver Regional Parks', 'SUR', NULL),
    ('regional-metro-vancouver-thw', 'Thwaytes Landing Regional Park', 'regional', 49.379307, -122.890777, 'South Coast', 'An officially mapped regional park in the South Coast collection. The pin represents its largest published polygon, not an entrance or trailhead.', 'https://open-data-portal-metrovancouver.hub.arcgis.com/datasets/metrovancouver::regional-parks-boundaries-open-data', 'Metro Vancouver Regional Parks', 'THW', NULL),
    ('regional-metro-vancouver-tla', 'ƛ̓éxətəm Regional Park', 'regional', 49.236851, -122.797459, 'South Coast', 'An officially mapped regional park in the South Coast collection. The pin represents its largest published polygon, not an entrance or trailhead.', 'https://open-data-portal-metrovancouver.hub.arcgis.com/datasets/metrovancouver::regional-parks-boundaries-open-data', 'Metro Vancouver Regional Parks', 'TLA', NULL),
    ('regional-metro-vancouver-tyn', 'Tynehead Regional Park', 'regional', 49.182593, -122.765891, 'South Coast', 'An officially mapped regional park in the South Coast collection. The pin represents its largest published polygon, not an entrance or trailhead.', 'https://open-data-portal-metrovancouver.hub.arcgis.com/datasets/metrovancouver::regional-parks-boundaries-open-data', 'Metro Vancouver Regional Parks', 'TYN', NULL),
    ('regional-metro-vancouver-wid', 'Widgeon Marsh Regional Park', 'regional', 49.351094, -122.647049, 'South Coast', 'An officially mapped regional park in the South Coast collection. The pin represents its largest published polygon, not an entrance or trailhead.', 'https://open-data-portal-metrovancouver.hub.arcgis.com/datasets/metrovancouver::regional-parks-boundaries-open-data', 'Metro Vancouver Regional Parks', 'WID', NULL),
    ('regional-mill-farm-regional-park', 'Mill Farm Regional Park', 'regional', 48.772312, -123.520294, 'Capital Region', 'On Salt Spring Island, forest trails pass a remnant waterwheel from an early logging operation and one of the Gulf Islands’ larger old-growth stands. Openings in the forest look toward Saanich Inlet and Cowichan Bay, and rare plants include the phantom orchid.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-mill-hill-regional-park', 'Mill Hill Regional Park', 'regional', 48.458273, -123.478383, 'Capital Region', 'Trails climb through Douglas-fir forest and Garry oak habitat to a rocky 203-metre summit. From the top, look over Esquimalt Harbour and the Victoria area.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-moorecroft-regional-park', 'Moorecroft Regional Park', 'regional', 49.303921, -124.180612, 'Central Island', 'This oceanfront park protects Garry oak meadows and coastal Douglas-fir habitat under a conservation covenant. Low-impact trails and picnic spots bring visitors to the shoreline, with views across the Salish Sea to the coastal mountains.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-mount-arrowsmith-massif-regional-park', 'Mount Arrowsmith Massif Regional Park', 'regional', 49.221214, -124.576717, 'Central Island', 'A high alpine park spanning Mount Arrowsmith and Mount Cokely, with flower-filled meadows in late spring and summer. Long-standing routes lead onto the ridges and are best suited to experienced hikers; the RDN recommends guided hikes for novices.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-mount-arrowsmith-regional-park-acrd', 'Mount Arrowsmith Regional Park (ACRD)', 'regional', 49.249953, -124.596061, 'Central Island', 'The northern Mount Cokely slope is reached by gravel logging roads and offers alpine hiking routes via Rousseau Trail, Arrowsmith Trail and the Lower Ski Area Trail. Access roads cross private forest land, so check Mosaic’s designated public access openings before setting out.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-mount-benson-regional-park', 'Mount Benson Regional Park', 'regional', 49.153826, -124.037915, 'Central Island', 'Forested slopes above Nanaimo open to views of the city and Strait of Georgia, while the park protects headwaters feeding nearby lakes and rivers. The approach from the parking lot is steep and rough in places; allow three to five hours for the return hike and prepare for changing weather.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-mount-cain-alpine-park', 'Mount Cain Alpine Park', 'regional', 50.222771, -126.345699, 'North Island', 'A community-operated ski area in the North Island mountains, Mount Cain is known for deep powder and backcountry terrain. Winter conditions and access change with weather, so check current local updates before travelling.', 'https://www.rdmw.bc.ca/recreation-leisure/', 'Regional District of Mount Waddington + OpenStreetMap contributors', 'W579980733', NULL),
    ('regional-mount-parke-regional-park', 'Mount Parke Regional Park', 'regional', 48.839428, -123.286546, 'Gulf Islands', 'A winding woodland trail on Mayne Island passes western red cedar, red alder and lush fern understory before reaching viewpoints. Spring wildflowers and birds of prey are among the seasonal highlights.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-mount-wells-regional-park', 'Mount Wells Regional Park', 'regional', 48.437335, -123.552788, 'Capital Region', 'This Sooke Hills wilderness park combines second-growth forest with fragile mossy rock outcrops and spring wildflowers. Viewpoints look toward Juan de Fuca Strait, Victoria and the Sea to Sea greenbelt.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-mount-work-regional-park', 'Mount Work Regional Park', 'regional', 48.531032, -123.477666, 'Capital Region', 'Three freshwater lakes, Killarney, Durrance and Pease, anchor a broad network of recreation trails. Visitors can walk or swim at the lakes; canoeing and fishing are available at Durrance and Pease, with rainbow trout stocked at Durrance.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-mountain-forest-regional-park', 'Mountain Forest Regional Park', 'regional', 48.50589, -123.428139, 'Capital Region', 'Mature Coastal Douglas-fir, Garry oak meadow, rocky outcrops and arbutus stands make up this rare-ecosystem landscape. The park also protects habitat for at-risk birds and headwaters of Excelsior Creek in the Colquitz River system.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-nanaimo-river-regional-park', 'Nanaimo River Regional Park', 'regional', 49.082725, -123.874246, 'Central Island', 'This conservation property protects a remnant of mature Coastal Douglas-fir forest along the lower Nanaimo River. Developed trails provide room to walk and cycle, the river is a swimming spot, and the southeast part is managed as wildlife habitat.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-osborne-bay-regional-park', 'Osborne Bay Regional Park', 'regional', 48.855811, -123.623265, 'Cowichan Valley', 'This 44-hectare Crofton waterfront park combines calm water, pebble beaches, open fields and nature trails. It offers public shoreline access, picnic space and year-round off-leash dog use.', 'https://maps.cvrd.ca/mapservices/rest/services/Parks/MapServer/2', 'Cowichan Valley Regional District — Parks GIS layer', '980261', NULL),
